  await d42Read(d42Keys.vale); t = await body();
  ok('D42 vale-alimentação: "· Vale" e "Dinheiro, débito ou Pix" escolhido', t.includes('· Vale') && (await d42Checked('Dinheiro, débito ou Pix')) === 'true');

